import {SITE,sitePath,assetPath,CONTACT} from './site-config.mjs';
import {SITE_COPY} from './site-copy.mjs';
import {STUDENT_CASES} from './student-cases.mjs';
export const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const messengerIcon='<svg data-messenger-icon viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2C6.48 2 2 6.14 2 11.25c0 2.91 1.45 5.51 3.72 7.21v3.15l3.05-1.68c1.02.33 2.1.51 3.23.51 5.52 0 10-4.14 10-9.19S17.52 2 12 2Zm1.05 12.44-2.55-2.72-4.97 2.72 5.46-5.8 2.6 2.72 4.91-2.72-5.45 5.8Z"/></svg>';
export const facebookIcon='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M22 12a10 10 0 1 0-11.56 9.88v-6.99H7.9V12h2.54V9.8c0-2.51 1.5-3.9 3.78-3.9 1.1 0 2.25.2 2.25.2v2.48H15.2c-1.24 0-1.63.78-1.63 1.57V12h2.78l-.44 2.89h-2.34v6.99A10 10 0 0 0 22 12Z"/></svg>';
export const pageUrl=sitePath;
export function messengerHtml(lang,classes='button',floating=false){const t=SITE_COPY[lang];return `<a class="${escapeHtml(classes)} messenger-cta${floating?' messenger-float':''}" data-consult data-messenger href="${CONTACT.messenger}" target="_blank" rel="noopener noreferrer" aria-label="${escapeHtml(t.free+' · '+t.newTab)}">${messengerIcon}<span${floating?' class="float-label"':''}>${escapeHtml(floating?'Messenger':t.free)}</span></a>`;}
const brand=lang=>`<a class="brand" href="${pageUrl('index',lang)}" aria-label="PyinNyar study abroad"><img class="brand-mark" src="${assetPath('assets/favicon.svg')}" width="43" height="43" alt=""><span><strong>PyinNyar</strong><small>study abroad</small></span></a>`;
const links=lang=>[['destinations','destinations',pageUrl('destinations',lang)],['scores','scores',pageUrl('match',lang)],['directory','directory',pageUrl('universities',lang)],['faq','faq',pageUrl('index',lang)+'#faq'],['contact','contact',pageUrl('index',lang)+'#contact']];
export function headerHtml(lang,page){const t=SITE_COPY[lang];return `<header class="header wrap ${page==='index'?'':'portal-header'}">${brand(lang)}<nav id="site-navigation" class="nav" aria-label="${escapeHtml(t.pages)}">${links(lang).map(([key,ui,href])=>`<a href="${href}" data-shell-label="${key}" data-ui="${ui}"${({destinations:'destinations',scores:'match',directory:'universities'})[key]===page?' aria-current="page"':''}>${escapeHtml(t[key])}</a>`).join('')}</nav><div class="header-actions"><div class="languages" role="group" aria-label="Language"><button type="button" data-lang="zh" lang="zh-CN" aria-pressed="${lang==='zh'}">中</button><button type="button" data-lang="my" lang="my" aria-pressed="${lang==='my'}">မြန်မာ</button><button type="button" data-lang="en" lang="en" aria-pressed="${lang==='en'}">EN</button></div>${messengerHtml(lang,'button small header-consult')}<button type="button" class="menu-toggle" aria-controls="site-navigation" aria-expanded="false" aria-label="${escapeHtml(t.menu)}"><span></span><span></span></button></div></header>`;}
export function footerHtml(lang){const t=SITE_COPY[lang];const extras=[['viber','Viber'],['whatsapp','WhatsApp'],['instagram','Instagram'],['email','Email'],['phone',t.contact]].filter(([k])=>CONTACT[k]);return `<footer class="footer wrap site-footer" id="contact"><div class="footer-grid"><div>${brand(lang)}<p class="footer-description" data-shell-label="footerDescription">${escapeHtml(t.footerDescription)}</p></div><nav class="footer-pages" aria-label="${escapeHtml(t.pages)}"><h2 data-shell-label="pages">${t.pages}</h2>${[['home',pageUrl('index',lang)],...links(lang).map(([k,,url])=>[k,url]),['scholarships',pageUrl('scholarships',lang)]].map(([k,url])=>`<a href="${url}" data-shell-label="${k}">${t[k]}</a>`).join('')}</nav><div class="footer-contact"><h2 data-shell-label="contactHeading">${t.contactHeading}</h2><p data-shell-label="contactNote">${escapeHtml(t.contactNote)}</p><div class="social-links">${messengerHtml(lang,'social-link')}<a class="social-link" href="${CONTACT.facebook}" target="_blank" rel="noopener noreferrer">${facebookIcon}<span data-shell-label="facebook">${t.facebook}</span></a>${extras.map(([k,label])=>`<a class="social-link" href="${escapeHtml(k==='email'?'mailto:'+CONTACT[k]:k==='phone'?'tel:'+CONTACT[k]:CONTACT[k])}">${escapeHtml(label)}</a>`).join('')}</div>${CONTACT.address?`<p>${escapeHtml(CONTACT.address)}</p>`:''}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} PyinNyar study abroad</span><span>中文 · <span lang="my">မြန်မာ</span> · English</span></div><!-- LANG LINKS START --><!-- LANG LINKS END --></footer>`;}
export function studentCasesHtml(lang){const cases=STUDENT_CASES.filter(c=>c.consentToPublish===true&&c.verified===true&&['zh','en','my'].every(l=>c.title?.[l]&&c.story?.[l]));if(!cases.length)return '';return `<section id="student-cases" class="section wrap" data-cases-lang="${lang}"><h2>${SITE_COPY[lang].casesTitle}</h2><div class="case-grid">${cases.map(c=>`<article>${c.photoUrl&&/^(https:\/\/|\/assets\/)/.test(c.photoUrl)?`<img src="${escapeHtml(c.photoUrl)}" alt="" loading="lazy">`:''}<h3>${escapeHtml(c.title[lang])}</h3><p>${escapeHtml(c.story[lang])}</p></article>`).join('')}</div></section>`;}
